@* The page owns the handoff data and the transport; the surface paints it and reports intent. *@
<TmAgentHandoff Steps="_steps"
               Title="Invoice run handoffs"
               @bind-ViewMode="_view"
               @bind-ExpandedStepIds="_expanded" />

@code {
    private IReadOnlyList<HandoffStep> _steps = [];
    private AgentHandoffViewMode _view = AgentHandoffViewMode.Chain;
    private IReadOnlyList<string>? _expanded;
}

var step = new HandoffStep("step-2", "The matcher takes over the invoice run")
{
    FromAgent = new AgentRef("Fetcher", "w-1") { ColorIndex = 1 },
    ToAgent = new AgentRef("Matcher", "w-2") { ColorIndex = 4 },
    At = now,
    Status = HandoffStatus.Accepted,
    PassedItems = [new HandoffItem("invoice schema", HandoffItemKind.Artifact)],
    LostItems = [new HandoffItem("conversation history").Lost("the context window was full")],
};

// Two steps in the chain render "2/3 handoffs · 3 passed on · 1 lost · 25 %".
